        "ResourceNotFoundException": SupportAuthZ.ResourceNotFoundException.self,
        "ServiceQuotaExceededException": SupportAuthZ.ServiceQuotaExceededException.self,
        "ThrottlingException": SupportAuthZ.ThrottlingException.self,
        "ValidationException": SupportAuthZ.ValidationException.self
    ]
}

extension SupportAuthZErrorType: Equatable {
